    'Copié !'=>['en'=>'Copied!','de'=>'Kopiert!','it'=>'Copiato!','es'=>'¡Copiado!'],
    'Nouvel élève dans votre cours liike'=>['en'=>'New student in your liike course','de'=>'Neue lernende Person in deinem liike-Kurs','it'=>'Nuovo studente nel tuo corso liike','es'=>'Nuevo alumno en tu curso de liike'],
    ':student a rejoint le cours « :course » avec son code d’invitation.'=>['en'=>':student joined “:course” using its invitation code.','de'=>':student ist dem Kurs «:course» mit dem Einladungscode beigetreten.','it'=>':student si è iscritto a «:course» con il codice di invito.','es'=>':student se ha unido a «:course» con el código de invitación.'],
    'Vous avez rejoint le cours « :course ».'=>['en'=>'You joined the course “:course”.','de'=>'Du bist dem Kurs «:course» beigetreten.','it'=>'Ti sei iscritto al corso «:course».','es'=>'Te has unido al curso «:course».'],
